34	func (h *handler) createUserHandler(w http.ResponseWriter, r *http.Request) {
35		if !request.IsAdminUser(r) {
36			response.JSONForbidden(w, r)
37			return
38		}
39	
40		var userCreationRequest model.UserCreationRequest
41		if err := json_parser.NewDecoder(r.Body).Decode(&userCreationRequest); err != nil {
42			response.JSONBadRequest(w, r, err)
43			return
44		}
45	
46		if validationErr := validator.ValidateUserCreationWithPassword(h.store, &userCreationRequest); validationErr != nil {
47			response.JSONBadRequest(w, r, validationErr.Error())
48			return
49		}
50	
51		user, err := h.store.CreateUser(&userCreationRequest)
52		if err != nil {
53			response.JSONServerError(w, r, err)
54			return
55		}
56	
57		response.JSONCreated(w, r, user)
58	}
